export interface TherapySection {
  heading: string;
  body: string[];
  media?: MediaItem[];
  /** Optional id used as an in-page anchor target (for the » table of contents). */
  anchor?: string;
  /** When true, the section is rendered inside a full-width tinted band. */
  tint?: boolean;
}

export interface MediaItem {
  type: 'image' | 'video';
  src: string;
  poster?: string;
  alt?: string;
}

export interface Treatment {
  slug: string;
  name: string;
  description: string;
  heroImage: string;
  thumb?: string;
  category: 'prosopo' | 'soma' | 'kliniki-dermatologia';
  tagline: string;
  sections: TherapySection[];
  bullets: string[];
  media?: MediaItem[];
  /** Optional » navigation shown as a tinted band above the content. */
  toc?: { label: string; anchor: string }[];
}

